UPDATE sms_coupon_history
SET use_status = 0,
    use_time = NULL
WHERE coupon_id = #{couponId}
  AND member_id = #{memberId}
  AND use_status = 1

UPDATE sms_coupon_history
SET use_status = 1,
    use_time = NOW()
WHERE coupon_id = #{couponId}
  AND member_id = #{memberId}
  AND use_status = 0
